import { z } from "zod";
import type { NotificationKind } from "@/types/notification";
import {
  notificationIdSchema,
  orgIdSchema,
  pageRequestSchema,
  userIdSchema,
} from "./common";

export const notificationKindSchema = z.enum([
  "issue_assigned",
  "issue_status_changed",
  "issue_due_soon",
  "issue_overdue",
  "comment_created",
  "comment_mention",
  "member_invited",
  "member_joined",
  "project_archived",
  "plan_limit_reached",
  "digest_ready",
]);

export const notificationChannelSchema = z.enum(["in_app", "email", "webhook"]);

export const markNotificationReadSchema = z.object({
  orgId: orgIdSchema,
  notificationId: notificationIdSchema,
});

export const markAllNotificationsReadSchema = z.object({
  orgId: orgIdSchema,
});

export const listNotificationsSchema = z
  .object({
    orgId: orgIdSchema,
    recipientId: userIdSchema,
    unreadOnly: z.boolean().default(false),
    kind: z.array(notificationKindSchema).optional(),
  })
  .extend(pageRequestSchema.shape);

export const updateNotificationPreferenceSchema = z.object({
  orgId: orgIdSchema,
  userId: userIdSchema,
  kind: notificationKindSchema,
  inApp: z.boolean(),
  email: z.boolean(),
  digestOnly: z.boolean(),
});

const _kindParity: NotificationKind = "comment_mention" satisfies z.infer<
  typeof notificationKindSchema
>;
void _kindParity;

export type MarkNotificationReadInput = z.infer<
  typeof markNotificationReadSchema
>;
export type ListNotificationsInput = z.infer<typeof listNotificationsSchema>;
export type UpdateNotificationPreferenceInput = z.infer<
  typeof updateNotificationPreferenceSchema
>;
---DBN
import { index, integer, sqliteTable, text, uniqueIndex } from "drizzle-orm/sqlite-core";
import { idColumn, tenantColumns, timestampColumns } from "./_shared";

const NOTIFICATION_KINDS = [
  "issue_assigned",
  "issue_status_changed",
  "issue_due_soon",
  "issue_overdue",
  "comment_created",
  "comment_mention",
  "member_invited",
  "member_joined",
  "project_archived",
  "plan_limit_reached",
  "digest_ready",
] as const;

export const notifications = sqliteTable(
  "notifications",
  {
    id: idColumn(),
    ...tenantColumns,
    recipientId: text("recipient_id").notNull(),
    kind: text("kind", { enum: NOTIFICATION_KINDS }).notNull(),
    title: text("title").notNull(),
    body: text("body").notNull(),
    href: text("href").notNull(),
    actorId: text("actor_id"),
    readAt: text("read_at"),
    /** JSON array of `NotificationChannel`. */
    channels: text("channels").notNull().default('["in_app"]'),
    ...timestampColumns,
  },
  (table) => [
    index("notifications_org_recipient_idx").on(table.orgId, table.recipientId),
    index("notifications_org_read_idx").on(table.orgId, table.readAt),
  ],
);

export const notificationPreferences = sqliteTable(
  "notification_preferences",
  {
    ...tenantColumns,
    userId: text("user_id").notNull(),
    kind: text("kind", { enum: NOTIFICATION_KINDS }).notNull(),
    inApp: integer("in_app", { mode: "boolean" }).notNull().default(true),
    email: integer("email", { mode: "boolean" }).notNull().default(true),
    digestOnly: integer("digest_only", { mode: "boolean" })
      .notNull()
      .default(false),
  },
  (table) => [
    uniqueIndex("notification_preferences_pk").on(
      table.orgId,
      table.userId,
      table.kind,
    ),
  ],
);

export type NotificationRow = typeof notifications.$inferSelect;
export type NewNotificationRow = typeof notifications.$inferInsert;
export type NotificationPreferenceRow =
  typeof notificationPreferences.$inferSelect;
---ACTS
import { z } from "zod";
import {
  isoTimestampSchema,
  orgIdSchema,
  pageRequestSchema,
  projectIdSchema,
  userIdSchema,
} from "./common";

export const activityActionSchema = z.enum([
  "organization.updated",
  "project.created",
  "project.updated",
  "project.archived",
  "project.restored",
  "issue.created",
  "issue.updated",
  "issue.status_changed",
  "issue.assigned",
  "issue.archived",
  "issue.restored",
  "comment.created",
  "comment.updated",
  "comment.deleted",
  "member.invited",
  "member.joined",
  "member.role_changed",
  "member.removed",
  "billing.plan_changed",
  "flag.toggled",
]);

export const activitySubjectKindSchema = z.enum([
  "organization",
  "project",
  "issue",
  "comment",
  "member",
  "subscription",
  "feature_flag",
]);

export const activityFilterSchema = z
  .object({
    orgId: orgIdSchema,
    action: z.array(activityActionSchema).optional(),
    actorId: userIdSchema.optional(),
    projectId: projectIdSchema.optional(),
    subjectKind: activitySubjectKindSchema.optional(),
    since: isoTimestampSchema.optional(),
    until: isoTimestampSchema.optional(),
  })
  .extend(pageRequestSchema.shape);

export const exportActivitySchema = z.object({
  orgId: orgIdSchema,
  since: isoTimestampSchema,
  until: isoTimestampSchema,
  format: z.enum(["csv", "json"]).default("csv"),
});

export type ActivityFilterInput = z.infer<typeof activityFilterSchema>;
export type ExportActivityInput = z.infer<typeof exportActivitySchema>;
---LABELS
/**
 * Presentation helpers for the audit trail.
 *
 * `ActivityEvent.summary` is written by the service layer and is authoritative;
 * these helpers only supply the verb chip and the day grouping the feed and the
 * per-issue panel both render, so the two views never disagree about what a
 * day boundary is.
 */
import type { ActivityAction, ActivityEvent, ActivityGroup } from "@/types/activity";

export const ACTIVITY_LABELS: Readonly<Record<ActivityAction, string>> = {
  "organization.updated": "updated the organization",
  "project.created": "created a project",
  "project.updated": "updated a project",
  "project.archived": "archived a project",
  "project.restored": "restored a project",
  "issue.created": "created an issue",
  "issue.updated": "updated an issue",
  "issue.status_changed": "changed status",
  "issue.assigned": "assigned an issue",
  "issue.archived": "archived an issue",
  "issue.restored": "restored an issue",
  "comment.created": "commented",
  "comment.updated": "edited a comment",
  "comment.deleted": "deleted a comment",
  "member.invited": "invited a member",
  "member.joined": "joined the organization",
  "member.role_changed": "changed a role",
  "member.removed": "removed a member",
  "billing.plan_changed": "changed the plan",
  "flag.toggled": "toggled a feature flag",
};

export function activityLabel(action: ActivityAction): string {
  return ACTIVITY_LABELS[action] ?? action;
}

/** The calendar day an event belongs to, in UTC (`YYYY-MM-DD`). */
export function activityDay(event: ActivityEvent): string {
  return event.occurredAt.slice(0, 10);
}

/**
 * Groups a flat event list into the day buckets `ActivityFeed` consumes,
 * newest day first and newest event first within a day.
 */
export function groupEventsByDay(
  events: readonly ActivityEvent[],
): readonly ActivityGroup[] {
  const byDay = new Map<string, ActivityEvent[]>();

  for (const event of events) {
    const day = activityDay(event);
    const bucket = byDay.get(day) ?? [];
    bucket.push(event);
    byDay.set(day, bucket);
  }

  return [...byDay.entries()]
    .sort(([a], [b]) => b.localeCompare(a))
    .map(([day, bucket]) => ({
      day,
      events: [...bucket].sort((a, b) =>
        b.occurredAt.localeCompare(a.occurredAt),
      ),
    }));
}
