  if (actor.userId !== org.ownerId) {
    throw new PermissionDeniedError("org:transfer_ownership", {
      allowed: false,
      action: "org:transfer_ownership",
      resourceKind: "organization",
      reason: "denied_by_role",
    });
  }
}

/** The open offer, provided it is addressed to `actor`. Anyone else gets `nothing_pending`. */
async function offerAddressedTo(actor: Actor, orgId: OrgId): Promise<OwnershipHandover> {
  const pending = await handoverRepo.findPendingHandover(orgId);
  if (!pending || pending.toUserId !== actor.userId) {
    throw new OwnershipHandoverError("nothing_pending");
  }
  if (hasLapsed(pending, new Date())) {
    throw new OwnershipHandoverError("expired");
  }
  return pending;
}

/**
 * Makes an offer to an active member. Only one offer may be open per workspace,
 * and the offered member is the only one alerted.
 */
export async function initiateOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
  toUserId: UserId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  await assertRecordedOwner(actor, orgId);

  if (toUserId === actor.userId) {
    throw new OwnershipHandoverError("self");
  }

  const target = await memberRepo.findMember(orgId, toUserId);
  if (!target || target.status !== "active") {
    throw new NotFoundError("Member", toUserId);
  }

  const now = new Date();
  const pending = await handoverRepo.findPendingHandover(orgId);
  if (pending) {
    if (!hasLapsed(pending, now)) {
      throw new OwnershipHandoverError("pending_exists");
    }
    // Close out the lapsed offer so the one-open-offer index frees up.
    await handoverRepo.resolveHandover(orgId, pending.id, "expired", pending.expiresAt);
  }

  const offer = await handoverRepo.insertHandover({
    orgId,
    fromUserId: actor.userId,
    toUserId,
    createdAt: toIsoTimestamp(now),
    expiresAt: toIsoTimestamp(new Date(now.getTime() + OWNERSHIP_OFFER_TTL_MS)),
  });

  await notify(orgId, "ownership_handover", [toUserId], {
    title: "Workspace ownership was offered to you",
    body: "Accept or decline the offer within seven days",
    href: "/settings/danger",
    actorId: actor.userId,
  });

  return offer;
}

/**
 * Accepting makes the offered member the recorded owner and gives them the owner
 * role; the previous owner steps down to admin. The new owner is promoted before
 * the old one is demoted, so the workspace never lacks an owner.
 */
export async function acceptOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<Organization> {
  assertOrgScope(actor, orgId);
  const offer = await offerAddressedTo(actor, orgId);

  const incoming = requireFound(
    await memberRepo.findMember(orgId, offer.toUserId),
    "Member",
    offer.toUserId,
  );
  const outgoing = await memberRepo.findMember(orgId, offer.fromUserId);

  if (incoming.role !== "owner") {
    await changeMemberRole(actor, incoming, "owner");
  }

  const updated = await orgRepo.setOrgOwner(orgId, offer.toUserId);

  if (outgoing?.role === "owner") {
    await changeMemberRole(actor, outgoing, "admin");
  }

  await handoverRepo.resolveHandover(
    orgId,
    offer.id,
    "accepted",
    toIsoTimestamp(new Date()),
  );

  await emit("organization.ownership_transferred", {
    ...actorEnvelope(actor),
    fromUserId: offer.fromUserId,
    toUserId: offer.toUserId,
  });

  return updated;
}

/** Role change made on the accepting member's behalf, announced like a manual change. */
async function changeMemberRole(actor: Actor, member: Member, role: Role): Promise<void> {
  const updated = await memberRepo.updateMemberRole(member.orgId, member.id, role);

  await emit("member.role_changed", {
    ...actorEnvelope(actor),
    memberId: updated.id,
    from: member.role,
    to: updated.role,
  });
}

/** The offered member turns the offer down; nothing is pending afterwards. */
export async function declineOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  const offer = await offerAddressedTo(actor, orgId);

  return handoverRepo.resolveHandover(
    orgId,
    offer.id,
    "declined",
    toIsoTimestamp(new Date()),
  );
}

/** The recorded owner withdraws an open offer. */
export async function cancelOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  await assertRecordedOwner(actor, orgId);

  const pending = await handoverRepo.findPendingHandover(orgId);
  if (!pending || hasLapsed(pending, new Date())) {
    throw new OwnershipHandoverError("nothing_pending");
  }

  return handoverRepo.resolveHandover(
    orgId,
    pending.id,
    "canceled",
    toIsoTimestamp(new Date()),
  );
}

/** The open offer for the workspace, visible to every member; `null` when none is open. */
export async function getPendingOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));

  const pending = await handoverRepo.findPendingHandover(orgId);
  if (!pending || hasLapsed(pending, new Date())) return null;
  return pending;
}

