/**
 * Ownership handover: offer, accept, decline and withdraw, the seven-day lapse,
 * and the role, event and alert consequences of acceptance.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { OwnershipHandoverError } from "@/lib/errors";
import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import { registerActivityListeners, listActivity } from "@/server/services/activity-service";
import * as billingService from "@/server/services/billing-service";
import * as memberRepo from "@/server/repositories/member-repository";
import * as memberService from "@/server/services/member-service";
import * as notificationService from "@/server/services/notification-service";
import * as organizationService from "@/server/services/organization-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";
import type { Actor } from "@/types/member";

const WEEK_MS = 7 * 24 * 60 * 60 * 1000;

let cleanup: () => void;
let detachActivity: Unsubscribe;
const detachers: Unsubscribe[] = [];

/** Collects every payload delivered for one event type during a test. */
function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

function asRole(tenant: Tenant, userId: string, role: Actor["role"]): Actor {
  return { userId: userId as Actor["userId"], orgId: tenant.org.id, role };
}

async function roleOf(tenant: Tenant, userId: string): Promise<string | undefined> {
  const member = await memberRepo.findMember(tenant.org.id, userId as Actor["userId"]);
  return member?.role;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detachActivity = registerActivityListeners();
});

afterEach(() => {
  vi.useRealTimers();
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  detachActivity();
  cleanup();
});

describe("services/organization-service ownership handover", () => {
  it("offers to an active member and alerts only that member", async () => {
    const tenant = await createTenant("handover-offer");
    const offer = await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.viewer,
    );

    expect(offer).toMatchObject({
      orgId: tenant.org.id,
      fromUserId: tenant.userIds.owner,
      toUserId: tenant.userIds.viewer,
      status: "pending",
      resolvedAt: null,
    });
    expect(Date.parse(offer.expiresAt) - Date.parse(offer.createdAt)).toBe(WEEK_MS);

    const alerted = await notificationService.listNotifications(tenant.actors.viewer, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.viewer,
      unreadOnly: false,
      kind: ["ownership_handover"],
      limit: 25,
      cursor: null,
    });
    expect(alerted.items).toHaveLength(1);

    const bystander = await notificationService.listNotifications(tenant.actors.admin, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.admin,
      unreadOnly: false,
      kind: ["ownership_handover"],
      limit: 25,
      cursor: null,
    });
    expect(bystander.items).toHaveLength(0);
  });

  it("refuses an offer to the owner themselves, and a second offer while one is open", async () => {
    const tenant = await createTenant("handover-self-pending");

    await expect(
      organizationService.initiateOwnershipHandover(
        tenant.actors.owner,
        tenant.org.id,
        tenant.userIds.owner,
      ),
    ).rejects.toMatchObject({ code: "conflict", reason: "self" });

    await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.viewer,
    );

    await expect(
      organizationService.initiateOwnershipHandover(
        tenant.actors.owner,
        tenant.org.id,
        tenant.userIds.admin,
      ),
    ).rejects.toMatchObject({ reason: "pending_exists" });
  });

  it("refuses an offer from a second owner-role member who is not the recorded owner", async () => {
    const tenant = await createTenant("handover-second-owner");
    const admin = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);
    if (!admin) throw new Error("fixture member missing");
    await memberService.updateMemberRole(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: admin.id,
      role: "owner",
    });

    await expect(
      organizationService.initiateOwnershipHandover(
        asRole(tenant, tenant.userIds.admin, "owner"),
        tenant.org.id,
        tenant.userIds.viewer,
      ),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });

  it("refuses an offer to a removed member, a non-member, or a member of another workspace", async () => {
    const tenant = await createTenant("handover-targets");
    const other = await createTenant("handover-elsewhere");
    const viewer = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!viewer) throw new Error("fixture member missing");
    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: viewer.id,
    });

    const offer = (userId: string) =>
      organizationService.initiateOwnershipHandover(
        tenant.actors.owner,
        tenant.org.id,
        userId as Actor["userId"],
      );

    await expect(offer(tenant.userIds.viewer)).rejects.toBeInstanceOf(NotFoundError);
    await expect(offer("01NOBODYNOBODYNOBODYNOBODY")).rejects.toBeInstanceOf(NotFoundError);
    await expect(offer(other.userIds.member)).rejects.toBeInstanceOf(NotFoundError);
  });

  it("accepts from any role: the accepting member becomes recorded owner, the previous owner steps down", async () => {
    const tenant = await createTenant("handover-accept");
    const roleChanges = capture("member.role_changed");
    const transfers = capture("organization.ownership_transferred");

    await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.viewer,
    );
    const updated = await organizationService.acceptOwnershipHandover(
      tenant.actors.viewer,
      tenant.org.id,
    );

    expect(updated.ownerId).toBe(tenant.userIds.viewer);
    expect(await roleOf(tenant, tenant.userIds.viewer)).toBe("owner");
    expect(await roleOf(tenant, tenant.userIds.owner)).toBe("admin");
    expect(await getPendingOrNull(tenant)).toBeNull();

    expect(roleChanges).toEqual([
      expect.objectContaining({
        orgId: tenant.org.id,
        actorId: tenant.userIds.viewer,
        memberId: expect.any(String),
        from: "viewer",
        to: "owner",
      }),
      expect.objectContaining({
        actorId: tenant.userIds.viewer,
        from: "owner",
        to: "admin",
      }),
    ]);
    expect(transfers).toEqual([
      expect.objectContaining({
        orgId: tenant.org.id,
        actorId: tenant.userIds.viewer,
        fromUserId: tenant.userIds.owner,
        toUserId: tenant.userIds.viewer,
      }),
    ]);

    const audit = await listActivity(tenant.actors.owner, {
      orgId: tenant.org.id,
      action: ["organization.ownership_transferred"],
      limit: 25,
      cursor: null,
    });
    expect(audit.items).toHaveLength(1);
    expect(audit.items[0]).toMatchObject({
      action: "organization.ownership_transferred",
      subjectKind: "organization",
      subjectId: tenant.org.id,
      metadata: { fromUserId: tenant.userIds.owner, toUserId: tenant.userIds.viewer },
    });

    // The previous owner is now an admin and has lost billing.
    await expect(
      billingService.getBillingSummary(
        asRole(tenant, tenant.userIds.owner, "admin"),
        tenant.org.id,
      ),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });

  it("changes only the previous owner's role when the accepting member already owns the workspace", async () => {
    const tenant = await createTenant("handover-already-owner");
    const admin = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);
    if (!admin) throw new Error("fixture member missing");
    await memberService.updateMemberRole(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: admin.id,
      role: "owner",
    });
    const roleChanges = capture("member.role_changed");

    await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.admin,
    );
    roleChanges.length = 0;
    await organizationService.acceptOwnershipHandover(
      asRole(tenant, tenant.userIds.admin, "owner"),
      tenant.org.id,
    );

    expect(roleChanges).toHaveLength(1);
    expect(roleChanges[0]).toMatchObject({ memberId: expect.any(String), from: "owner", to: "admin" });
    expect(await roleOf(tenant, tenant.userIds.admin)).toBe("owner");
    expect(await roleOf(tenant, tenant.userIds.owner)).toBe("admin");
  });

  it("lapses seven days after the offer is made", async () => {
    const tenant = await createTenant("handover-lapse");
    const start = new Date("2031-03-01T09:00:00.000Z");
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(start);

    await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.viewer,
    );

    vi.setSystemTime(new Date(start.getTime() + WEEK_MS - 1));
    expect(await getPendingOrNull(tenant)).not.toBeNull();

    vi.setSystemTime(new Date(start.getTime() + WEEK_MS));
    expect(await getPendingOrNull(tenant)).toBeNull();
    await expect(
      organizationService.acceptOwnershipHandover(tenant.actors.viewer, tenant.org.id),
    ).rejects.toMatchObject({ reason: "expired" });
    await expect(
      organizationService.declineOwnershipHandover(tenant.actors.viewer, tenant.org.id),
    ).rejects.toMatchObject({ reason: "expired" });
    await expect(
      organizationService.cancelOwnershipHandover(tenant.actors.owner, tenant.org.id),
    ).rejects.toMatchObject({ reason: "nothing_pending" });
    expect(await roleOf(tenant, tenant.userIds.viewer)).toBe("viewer");

    // A lapsed offer no longer blocks a new one.
    const next = await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.admin,
    );
    expect(next.toUserId).toBe(tenant.userIds.admin);
  });

  it("refuses acceptance or declining by anyone but the offered member, and nothing once it is closed", async () => {
    const tenant = await createTenant("handover-nothing-pending");
    await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.viewer,
    );

    await expect(
      organizationService.acceptOwnershipHandover(tenant.actors.admin, tenant.org.id),
    ).rejects.toMatchObject({ reason: "nothing_pending" });
    await expect(
      organizationService.declineOwnershipHandover(tenant.actors.owner, tenant.org.id),
    ).rejects.toMatchObject({ reason: "nothing_pending" });

    const declined = await organizationService.declineOwnershipHandover(
      tenant.actors.viewer,
      tenant.org.id,
    );
    expect(declined).toMatchObject({ status: "declined", resolvedAt: expect.any(String) });
    await expect(
      organizationService.declineOwnershipHandover(tenant.actors.viewer, tenant.org.id),
    ).rejects.toMatchObject({ reason: "nothing_pending" });
    await expect(
      organizationService.acceptOwnershipHandover(tenant.actors.viewer, tenant.org.id),
    ).rejects.toMatchObject({ reason: "nothing_pending" });

    // Declining leaves the owner free to offer again.
    await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.admin,
    );
    expect(await roleOf(tenant, tenant.userIds.owner)).toBe("owner");
  });

  it("lets only the recorded owner withdraw, and refuses a withdrawal when nothing is open", async () => {
    const tenant = await createTenant("handover-withdraw");
    await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.viewer,
    );

    await expect(
      organizationService.cancelOwnershipHandover(tenant.actors.admin, tenant.org.id),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    const canceled = await organizationService.cancelOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
    );
    expect(canceled).toMatchObject({ status: "canceled", resolvedAt: expect.any(String) });
    expect(await getPendingOrNull(tenant)).toBeNull();

    await expect(
      organizationService.cancelOwnershipHandover(tenant.actors.owner, tenant.org.id),
    ).rejects.toMatchObject({ reason: "nothing_pending" });
  });

  it("withdraws an open offer when the offered member leaves the workspace", async () => {
    const tenant = await createTenant("handover-target-removed");
    await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.viewer,
    );
    const viewer = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!viewer) throw new Error("fixture member missing");

    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: viewer.id,
    });

    expect(await getPendingOrNull(tenant)).toBeNull();
  });

  it("refuses every operation on another workspace's id with a tenant scope error", async () => {
    const tenant = await createTenant("handover-scope-a");
    const other = await createTenant("handover-scope-b");
    const outsider = asRole(other, other.userIds.owner, "owner");

    await expect(
      organizationService.getPendingOwnershipHandover(outsider, tenant.org.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      organizationService.initiateOwnershipHandover(outsider, tenant.org.id, tenant.userIds.viewer),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      organizationService.acceptOwnershipHandover(outsider, tenant.org.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });
});

/** The open offer as seen by the owner, or `null`. */
async function getPendingOrNull(tenant: Tenant) {
  return organizationService.getPendingOwnershipHandover(tenant.actors.owner, tenant.org.id);
}

void OwnershipHandoverError;

