import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";
import type { Actor } from "@/types/member";

const WEEK_MS = 7 * 24 * 60 * 60 * 1000;

let cleanup: () => void;
let detachActivity: Unsubscribe;
const detachers: Unsubscribe[] = [];

/** Collects every payload delivered for one event type during a test. */
function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

function asRole(tenant: Tenant, userId: string, role: Actor["role"]): Actor {
  return { userId: userId as Actor["userId"], orgId: tenant.org.id, role };
}

async function roleOf(tenant: Tenant, userId: string): Promise<string | undefined> {
  const member = await memberRepo.findMember(tenant.org.id, userId as Actor["userId"]);
  return member?.role;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detachActivity = registerActivityListeners();
});

afterEach(() => {
  vi.useRealTimers();
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  detachActivity();
  cleanup();
});

